// Parsea el JSON devuelto por Gemini Vision y construye el contexto para el agente
const raw = $input.first().json;

// Gemini puede devolver el texto en varias ubicaciones según la versión del nodo:
let rawText = '';
if (raw.content?.parts?.[0]?.text) {
  rawText = raw.content.parts[0].text;
} else if (raw.response?.text) {
  rawText = raw.response.text;
} else if (raw.text) {
  rawText = raw.text;
} else if (typeof raw === 'string') {
  rawText = raw;
} else {
  rawText = JSON.stringify(raw);
}

let analisis;
try {
  const clean = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
  analisis = JSON.parse(clean);
} catch (e) {
  return {
    json: {
      ok: false,
      error: 'No se pudo interpretar el análisis de la imagen',
      raw: rawText,
      contexto_imagen: '[IMAGEN RECIBIDA] No pude analizarla. Pide al cliente que describa lo que busca.'
    }
  };
}

let query_sugerido = '';
if (analisis.marca && analisis.marca !== 'null' && analisis.marca !== null) {
  query_sugerido = `${analisis.tipo_producto} ${analisis.marca}`.trim();
} else if (analisis.tipo_producto && analisis.tipo_producto !== 'Desconocido') {
  query_sugerido = analisis.tipo_producto;
}

let contexto_imagen;
if (query_sugerido) {
  contexto_imagen = `[IMAGEN RECIBIDA DEL CLIENTE] Analicé la imagen y detecté: tipo=${analisis.tipo_producto}, marca=${analisis.marca || 'no identificada'}, confianza=${analisis.confianza}. Llama a buscar_productos con query='${query_sugerido}' y presenta las opciones al cliente en formato numérico.`;
} else {
  contexto_imagen = `[IMAGEN RECIBIDA DEL CLIENTE] No pude identificar un producto de limpieza claro en la imagen. Pregunta al cliente qué busca con palabras.`;
}

return {
  json: {
    ok: true,
    tipo_producto: analisis.tipo_producto || 'Desconocido',
    marca: analisis.marca || null,
    descripcion_breve: analisis.descripcion_breve || '',
    palabras_clave: analisis.palabras_clave_busqueda || [],
    confianza: analisis.confianza || 'baja',
    query_sugerido,
    contexto_imagen
  }
};
